</button><button class="btn primary">Guardar ubicación</button></div></form></div></dialog>
<dialog class="location-dialog" id="unit-modal"><div class="modal-inner"><div class="modal-head"><h2><?=$editUnit?'Editar unidad':'Nueva unidad'?></h2><button type="button" data-close-modal aria-label="Cerrar">×</button></div>
<form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="unidad_save"><input type="hidden" name="id" value="<?=e($editUnit['id']??0)?>">
<div class="full"><label class="field-label">Ubicación a la que pertenece * <span class="info-icon" title="Selecciona el inmueble donde está esta unidad. Ejemplo: Piso de Palma." aria-label="Ayuda sobre la ubicación de la unidad">i</span></label><select name="ubicacion_id" id="unit-location" required><?php foreach($locations as $l):?><option value="<?=$l['id']?>" <?=((int)($editUnit['ubicacion_id']??0)===(int)$l['id'])?'selected':''?>><?=e($l['nombre'])?></option><?php endforeach;?></select></div><div class="full"><label class="field-label">Nombre de la unidad * <span class="info-icon" title="Nombre del espacio concreto que se alquila o gestiona. Ejemplo: Habitación A o Vivienda principal." aria-label="Ayuda sobre el nombre de unidad">i</span></label><input name="nombre" required value="<?=e($editUnit['nombre']??'')?>" placeholder="Ej. Vivienda principal, Habitación A"></div><div class="full"><label class="field-label">Tipo de unidad <span class="info-icon" title="Clasifica el espacio concreto, no el inmueble completo." aria-label="Ayuda sobre el tipo de unidad">i</span></label><select name="tipo_unidad"><?php foreach(['VIVIENDA'=>'Vivienda','HABITACION'=>'Habitación','LOCAL'=>'Local','OTRA'=>'Otra unidad'] as $v=>$label):?><option value="<?=$v?>" <?=($editUnit['tipo']??'VIVIENDA')===$v?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></div><div class="full"><label>Estado</label><select name="estado_unidad"><option value="ACTIVA" <?=($editUnit['estado']??'ACTIVA')==='ACTIVA'?'selected':''?>>Activa</option><option value="INACTIVA" <?=($editUnit['estado']??'ACTIVA')==='INACTIVA'?'selected':''?>>Inactiva</option></select></div><div class="full"><label>Descripción</label><textarea name="descripcion_unidad" rows="2"><?=e($editUnit['descripcion']??'')?></textarea></div><div class="full modal-actions"><button type="button" class="btn outline" data-close-modal>Cancelar</button><button class="btn primary">Guardar unidad</button></div></form></div></dialog>
<script>
document.querySelectorAll('[data-open-modal]').forEach(button=>button.addEventListener('click',()=>{const modal=document.getElementById(button.dataset.openModal);if(button.dataset.locationId){const select=document.getElementById('unit-location');if(select)select.value=button.dataset.locationId;}if(modal)modal.showModal();}));
document.querySelectorAll('[data-close-modal]').forEach(button=>button.addEventListener('click',()=>button.closest('dialog').close()));
document.querySelectorAll('dialog').forEach(dialog=>dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close();}));
const search=document.getElementById('location-search'),typeFilter=document.getElementById('location-type'),statusFilter=document.getElementById('location-status');
function filterLocations(){const cards=[...document.querySelectorAll('.property-card')];const query=(search?.value||'').trim().toLocaleLowerCase();let visible=0;cards.forEach(card=>{const show=card.dataset.name.includes(query)&&(!typeFilter.value||card.dataset.type===typeFilter.value)&&(!statusFilter.value||card.dataset.status===statusFilter.value);card.hidden=!show;if(show)visible++;});const count=document.getElementById('result-count');if(count)count.textContent=visible+' resultado'+(visible===1?'':'s');const empty=document.getElementById('no-filter-results');if(empty)empty.hidden=visible>0;}
[search,typeFilter,statusFilter].forEach(el=>el?.addEventListener(el===search?'input':'change',filterLocations));
<?php if($editLoc):?>document.getElementById('location-modal').showModal();<?php endif;?>
<?php if($editUnit):?>document.getElementById('unit-modal').showModal();<?php endif;?>
</script><script>document.addEventListener('DOMContentLoaded',()=>{const nav=document.querySelector('.sidebar');if(!nav)return;const btn=nav.querySelector('.mobile-menu-toggle');const links=nav.querySelector('.mobile-nav-links');if(!btn||!links)return;links.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{if(window.matchMedia('(max-width:650px)').matches){nav.classList.remove('mobile-menu-open');btn.setAttribute('aria-expanded','false');btn.querySelector('.toggle-label').textContent='Menú principal';btn.querySelector('.toggle-icon').textContent='☰';}}));});</script></body></html>